from pathlib import Path
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.skip=0; self.out=[]
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
  if t=='a' and not self.skip: self.out.append('LINK '+dict(a).get('href',''))
 def handle_endtag(self,t):
  if t in ('script','style'): self.skip=max(0,self.skip-1)
 def handle_data(self,d):
  if not self.skip and d.strip(): self.out.append(d.strip())
p=P();p.feed(Path('products/research/wordpress-paid-fit/jobs.html').read_text()); s='\n'.join(p.out);Path('products/research/wordpress-paid-fit/extract.txt').write_text(s);print(s[:18000])
